package com.tradepilot.backtest.entity;
import jakarta.persistence.*; import org.hibernate.annotations.ColumnTransformer; import java.time.*; import java.math.*;
@Entity @Table(name="backtest_runs") public class BacktestRun {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false) private Long userId; @Column(nullable=false,length=10) private String instrument; @Column(name="strategy_version",nullable=false,length=40) private String strategyVersion; @Column(name="start_date",nullable=false) private LocalDate startDate; @Column(name="end_date",nullable=false) private LocalDate endDate; @Column(name="config_json",nullable=false,columnDefinition="jsonb") @ColumnTransformer(read="config_json::text",write="?::jsonb") private String configJson; @Column(name="result_json",columnDefinition="jsonb") @ColumnTransformer(read="result_json::text",write="?::jsonb") private String resultJson; @Column(nullable=false,length=20) private String status; @Column(name="error_message",length=500) private String errorMessage; @Column(name="started_at") private Instant startedAt; @Column(name="completed_at") private Instant completedAt; @Column(name="total_trades") private Integer totalTrades; @Column(name="win_rate",precision=10,scale=6) private BigDecimal winRate; @Column(name="total_r",precision=16,scale=6) private BigDecimal totalR; @Column(name="weighted_total_r",precision=16,scale=6) private BigDecimal weightedTotalR; @Column(precision=16,scale=6) private BigDecimal expectancy; @Column(name="max_drawdown_r",precision=16,scale=6) private BigDecimal maxDrawdownR; @Column(name="created_at",nullable=false) private Instant createdAt;
 public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getInstrument(){return instrument;} public void setInstrument(String v){instrument=v;} public String getStrategyVersion(){return strategyVersion;} public void setStrategyVersion(String v){strategyVersion=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getConfigJson(){return configJson;} public void setConfigJson(String v){configJson=v;} public String getResultJson(){return resultJson;} public void setResultJson(String v){resultJson=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getErrorMessage(){return errorMessage;} public void setErrorMessage(String v){errorMessage=v;} public void setStartedAt(Instant v){startedAt=v;} public void setCompletedAt(Instant v){completedAt=v;} public void metrics(int n,BigDecimal w,BigDecimal t,BigDecimal e,BigDecimal d){totalTrades=n;winRate=w;weightedTotalR=t;totalR=t;expectancy=e;maxDrawdownR=d;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;}
}
